    async def changes(
        self,
        brain_id: str,
        *,
        limit: typing.Optional[int] = None,
        offset: typing.Optional[int] = None,
        unacked_only: typing.Optional[bool] = None,
        page_id: typing.Optional[str] = None,
        since: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncPager[ChangeEvent, ChangeList]:
        """
        List change-feed events with offset pagination. This is the primary way to sync an external system: poll with `since`, or filter to `unackedOnly` to build an inbox.

        Parameters
        ----------
        brain_id : str
            Brain id

        limit : typing.Optional[int]

        offset : typing.Optional[int]

        unacked_only : typing.Optional[bool]

        page_id : typing.Optional[str]

        since : typing.Optional[str]
            ISO timestamp

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncPager[ChangeEvent, ChangeList]


        Examples
        --------
        import asyncio

        from livingbrain import AsyncLivingBrain

        client = AsyncLivingBrain(
            subject_id="YOUR_SUBJECT_ID",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            response = await client.workspace.changes(
                brain_id="brainId",
            )
            async for item in response:
                yield item

            # alternatively, you can paginate page-by-page
            async for page in response.iter_pages():
                yield page


        asyncio.run(main())
        """
        return await self._raw_client.changes(
            brain_id,
            limit=limit,
            offset=offset,
            unacked_only=unacked_only,
            page_id=page_id,
            since=since,
            request_options=request_options,
        )

